import * as THREE from "three";export class Controls{constructor(player){this.player=player;this.move=new THREE.Vector2();this.joy=document.querySelector("#joy");this.knob=document.querySelector("#knob");this.id=null;this.keys=new Set();this.joy.addEventListener("pointerdown",e=>{e.preventDefault();this.id=e.pointerId;this.joy.setPointerCapture(e.pointerId);this.center=this.joy.getBoundingClientRect();this.moveJoy(e)});this.joy.addEventListener("pointermove",e=>{if(e.pointerId===this.id)this.moveJoy(e)});const up=e=>{if(e.pointerId===this.id){this.id=null;this.move.set(0,0);this.knob.style.transform="translate(0,0)"}};this.joy.addEventListener("pointerup",up);this.joy.addEventListener("pointercancel",up);addEventListener("keydown",e=>this.keys.add(e.code));addEventListener("keyup",e=>this.keys.delete(e.code));let last=null;document.addEventListener("pointerdown",e=>{if(e.clientX>innerWidth*.42&&!e.target.closest("button")&&!e.target.closest("#joy"))last=e.clientX});document.addEventListener("pointermove",e=>{if(last!==null&&e.buttons){this.player.yaw-=(e.clientX-last)*.006;last=e.clientX}});document.addEventListener("pointerup",()=>last=null)}moveJoy(e){let x=e.clientX-(this.center.left+this.center.width/2),y=e.clientY-(this.center.top+this.center.height/2),l=Math.hypot(x,y),r=47;if(l>r){x=x/l*r;y=y/l*r}this.move.set(x/r,-y/r);this.knob.style.transform=`translate(${x}px,${y}px)`}update(){let x=0,y=0;if(this.keys.has("KeyA")||this.keys.has("ArrowLeft"))x--;if(this.keys.has("KeyD")||this.keys.has("ArrowRight"))x++;if(this.keys.has("KeyW")||this.keys.has("ArrowUp"))y++;if(this.keys.has("KeyS")||this.keys.has("ArrowDown"))y--;if(x||y)this.move.set(x,y).normalize()}}